fn frombuffer(buffer: &Vec<u8>, count: usize, offset: usize) -> Vec<u8> {
    // Safety: We assume offset + count <= buffer.len() (as per problem statement),
    // and slices in Rust allow offset == buffer.len() when count == 0.
    buffer[offset..offset + count].to_vec()
}

